import pdfplumber
import pubchempy as pcp
from rdkit import Chem
from rdkit import DataStructs
from rdkit.Chem import AllChem
import os

def get_fingerprint(smiles):
    if not smiles:
        return None
    mol = Chem.MolFromSmiles(smiles)
    if mol:
        return AllChem.GetMorganFingerprintAsBitVect(mol, 2, nBits=2048, useChirality=True)
    return None

def extract_names_from_pdf(filepath):
    names = []
    if not os.path.exists(filepath):
        return names
    with pdfplumber.open(filepath) as pdf:
        for page in pdf.pages:
            text = page.extract_text()
            if text:
                for line in text.split('\n'):
                    name = line.strip()
                    if name:
                        names.append(name)
    return names

def topk_tanimoto_similarity_molecules(target_molecule_name, molecule_pool_filepath, top_k):
    # Get target SMILES
    try:
        target_compounds = pcp.get_compounds(target_molecule_name, 'name')
        if not target_compounds:
            return []
        target_smiles = target_compounds[0].isomeric_smiles
        target_fp = get_fingerprint(target_smiles)
        if not target_fp:
            return []
    except Exception:
        return []

    # Get pool names from PDF
    pool_names = extract_names_from_pdf(molecule_pool_filepath)

    results = []
    seen_names = set()

    # Cache for name to SMILES to avoid redundant API calls if names repeat
    name_to_smiles = {}

    for name in pool_names:
        if name in seen_names:
            continue
        seen_names.add(name)

        try:
            # Check if we already looked up this name
            if name not in name_to_smiles:
                compounds = pcp.get_compounds(name, 'name')
                if compounds:
                    name_to_smiles[name] = compounds[0].isomeric_smiles
                else:
                    name_to_smiles[name] = None

            smiles = name_to_smiles[name]
            if smiles:
                fp = get_fingerprint(smiles)
                if fp:
                    similarity = DataStructs.TanimotoSimilarity(target_fp, fp)
                    results.append((name, similarity))
        except Exception:
            continue

    # Sort: similarity descending, then name alphabetical ascending
    results.sort(key=lambda x: (-x[1], x[0]))

    # The prompt says "Find the top k similar chemicals", 
    # usually this means returning the names and their similarities or just names.
    # Given the requirements about sorting, I will return the list of tuples (name, similarity).
    return results[:top_k]

if __name__ == "__main__":
    # Example usage or test if needed
    # results = topk_tanimoto_similarity_molecules("Aspirin", "molecules.pdf", 5)
    # for name, score in results:
    #     print(f"{name}: {score:.4f}")
